   140	/**
   141	 * @brief 创建图层要素迭代器。
   142	 */
   143	vmap_feature_iter_t vmap_tile_layer_iter(const vmap_tile_t * tile, uint8_t layer_id)
   144	{
   145	    vmap_feature_iter_t it = { 0 };
   146	    if (!tile) {
   147	        return it;
   148	    }
   149	
   150	    for (uint16_t i = 0; i < tile->num_layers; i++) {
   151	        if (tile->layers[i].id == layer_id) {
   152	            it.ptr = tile->layers[i].data;
   153	            it.end = tile->layers[i].data + tile->layers[i].bytes;
   154	            it.remaining = tile->layers[i].feature_count;
   155	            break;
   156	        }
   157	    }
   158	    return it;
   159	}
   160	
   161	/**
   162	 * @brief 迭代下一个要素。
   163	 * @param it 迭代器。
   164	 * @param out 输出要素。
   165	 */
   166	bool vmap_feature_iter_next(vmap_feature_iter_t * it, vmap_feature_t * out)
   167	{
   168	    if (!it || !out || it->remaining == 0 || !it->ptr || it->ptr + 4 > it->end) {
   169	        return false;
   170	    }
   171	
   172	    out->attr = it->ptr[0];
   173	    out->flags = it->ptr[1];
   174	    out->point_count = rd_u16(it->ptr + 2);
   175	    const uint8_t * coords = it->ptr + 4;
   176	    const uint8_t * nextp = coords + (size_t)out->point_count * 4;
   177	
   178	    out->coords = (const uint16_t *)coords;
   179	    out->name_text = NULL;
   180	    out->name_len = 0;
   181	    if (out->flags & VMAP_FLAG_NAMED) {
   182	        if (nextp + 1 > it->end) {
   183	            it->remaining = 0;
   184	            return false;
   185	        }
   186	        out->name_len = nextp[0];
   187	        out->name_text = (const char *)(nextp + 1);
   188	        nextp += 1u + out->name_len;
   189	    }
   190	
   191	    if (nextp > it->end) {
   192	        it->remaining = 0;
   193	        return false;
   194	    }
   195	
   196	    it->ptr = nextp;
   197	    it->remaining--;
   198	    return true;
   199	}
